function UnbilledModal({data,close,done}:{data:Row;close:()=>void;done:()=>void}){
 const[rate,setRate]=useState(String(data.hourlyRate||2500)),[busy,setBusy]=useState(''),[err,setErr]=useState('');
 async function bill(clientId:string){setBusy(clientId);setErr('');try{await api('/api/support/invoice',{method:'POST',body:JSON.stringify({clientId,hourlyRate:Number(rate),issue:true})});done()}catch(e){setErr((e as Error).message)}finally{setBusy('')}}
 return <Modal title="Facturar soporte" close={close}><div className="unbilled-list"><label className="rate-input">Tarifa por hora (RD$) <input type="number" value={rate} onChange={e=>setRate(e.target.value)}/></label>{err&&<div className="live-error">{err}</div>}{(data.clients||[]).map((c:Row)=><div key={c.client_id}><div><b>{c.client_name}</b><small>{c.ticket_count} tickets · {c.hours}h · {c.entry_count} registros</small></div><span>{M(Math.round((c.minutes/60)*Number(rate)*100)/100)}</span><button className="primary-btn" disabled={!!busy} onClick={()=>bill(c.client_id)}>Facturar</button></div>)}</div></Modal>;
}
function Thread({ticket,user,close,refresh}:{ticket:Row;user:User;close:()=>void;refresh:()=>void}){
 const[full,setFull]=useState<Row|null>(null),[messages,setMessages]=useState<Row[]>([]),[body,setBody]=useState(''),[minutes,setMinutes]=useState('0'),[internal,setInternal]=useState(false),[err,setErr]=useState('');
 const staff=user.role!=='CLIENT';
 const load=()=>Promise.all([api(`/api/tickets/${ticket.id}/messages`).then(d=>setMessages(d.messages||[])),staff?api(`/api/tickets/${ticket.id}`).then(setFull):Promise.resolve()]);
 useEffect(()=>{load()},[]);
 const t=full?.ticket||ticket;
 async function patch(body:Row){try{await api(`/api/tickets/${ticket.id}`,{method:'PATCH',body:JSON.stringify(body)});await load();refresh()}catch(e){setErr((e as Error).message)}}
 async function send(){if(!body.trim())return;try{await api(`/api/tickets/${ticket.id}/messages`,{method:'POST',body:JSON.stringify({body,internal,billableMinutes:Number(minutes)||0})});setBody('');setMinutes('0');setInternal(false);await load();refresh()}catch(e){setErr((e as Error).message)}}
 return <Modal title={`${ticket.number} · ${ticket.subject}`} close={close}>
  {err&&<div className="live-error" style={{margin:'0 18px'}}>{err}</div>}
  {staff&&<div className="ticket-props">
   <label>Estado<select value={t.status} onChange={e=>patch({status:e.target.value})}><option>OPEN</option><option>IN_PROGRESS</option><option>WAITING_CLIENT</option><option>RESOLVED</option><option>CLOSED</option></select></label>
   <label>Prioridad<select value={t.priority} onChange={e=>patch({priority:e.target.value})}><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>URGENT</option></select></label>
   <div className="sla-props"><SlaBar c={t.sla?.firstResponse} label="1ª respuesta"/><SlaBar c={t.sla?.resolution} label="Resolución"/>{t.sla?.paused&&<small>SLA en pausa (esperando cliente)</small>}{t.escalation_level>0&&<small className="danger">Escalado</small>}</div>
  </div>}
  <div className="thread">{messages.map(m=><article key={m.id} className={`${m.author_id===user.id?'mine':''} ${m.internal?'internal':''}`}><b>{m.author_name}{m.internal?' · nota interna':''}</b><p>{m.body}</p><small>{D(m.created_at)}</small></article>)}</div>
  <div className="thread-compose"><textarea value={body} onChange={e=>setBody(e.target.value)} placeholder={internal?'Nota interna…':'Responder al cliente…'}/>{staff&&<input type="number" value={minutes} onChange={e=>setMinutes(e.target.value)} placeholder="Min." title="Minutos facturables"/>}<button className="primary-btn" onClick={send}>Enviar</button></div>
  {staff&&<label className="internal-toggle"><input type="checkbox" checked={internal} onChange={e=>setInternal(e.target.checked)}/> Nota interna (no visible al cliente)</label>}
 </Modal>;
}

function Modal({title,close,children}:{title:string;close:()=>void;children:React.ReactNode}){return <div className="live-modal-bg"><section className="live-modal"><header><h2>{title}</h2><button onClick={close}>×</button></header>{children}</section></div>}
function CommandPalette({close,go}:{close:()=>void;go:(m:string)=>void}){
 const[q,setQ]=useState(''),[res,setRes]=useState<Row[]>([]),[i,setI]=useState(0);
 useEffect(()=>{let done=false;const t=setTimeout(()=>{if(done)return;if(q.trim().length<2){setRes([]);return}api(`/api/search?q=${encodeURIComponent(q)}`).then(d=>{if(!done){setRes(d.results||[]);setI(0)}}).catch(()=>{if(!done)setRes([])})},180);return()=>{done=true;clearTimeout(t)}},[q]);
 function key(e:React.KeyboardEvent){if(e.key==='ArrowDown'){e.preventDefault();setI(x=>Math.min(x+1,res.length-1))}if(e.key==='ArrowUp'){e.preventDefault();setI(x=>Math.max(x-1,0))}if(e.key==='Enter'&&res[i])go(res[i].module)}
 return <div className="cmd-bg" onMouseDown={close}><div className="cmd" onMouseDown={e=>e.stopPropagation()}>
  <div className="cmd-input">◎<input autoFocus placeholder="Buscar clientes, facturas, tickets, propuestas, proyectos…" value={q} onChange={e=>setQ(e.target.value)} onKeyDown={key}/><kbd>ESC</kbd></div>
  <div className="cmd-results">{res.length===0&&q.trim().length>=2&&<div className="cmd-empty">Sin resultados</div>}{res.map((r,idx)=><button key={r.type+r.id} className={idx===i?'sel':''} onMouseEnter={()=>setI(idx)} onClick={()=>go(r.module)}><span className="cmd-type">{r.type}</span><span className="cmd-title">{r.title}</span><span className="cmd-sub">{r.subtitle}</span></button>)}</div>
  <div className="cmd-foot"><span><kbd>↑</kbd><kbd>↓</kbd> navegar</span><span><kbd>↵</kbd> abrir módulo</span></div>
 </div></div>;
}
function Create({type,user,close,done}:{type:Key;user:User;close:()=>void;done:()=>void}){const[f,setF]=useState<Record<string,any>>({priority:'MEDIUM',stage:'QUALIFIED',probability:25,type:'DOMAIN',issue:true,method:'TRANSFER'}),[clients,setClients]=useState<Row[]>([]),[invoices,setInvoices]=useState<Row[]>([]),[items,setItems]=useState([{description:'Servicios profesionales',quantity:1,unitPrice:0,taxRate:18}]),[err,setErr]=useState('');useEffect(()=>{if(type!=='clients')api('/api/clients').then(d=>setClients(d.clients||[]));if(type==='payments')api('/api/invoices').then(d=>setInvoices(d.invoices||[]))},[type]);const S=(k:string,v:any)=>setF(x=>({...x,[k]:v}));async function submit(e:React.FormEvent){e.preventDefault();try{const map:any={clients:'/api/clients',sales:'/api/opportunities',proposals:'/api/proposals',projects:'/api/projects',billing:'/api/invoices',payments:'/api/payments',support:'/api/tickets',assets:'/api/assets'};const withLines=type==='billing'||type==='proposals';const payload=withLines?{...f,items,milestones:type==='proposals'?(f.milestones||[]).filter((m:any)=>m&&m.label):undefined}:f;await api(map[type],{method:'POST',body:JSON.stringify(payload)});done()}catch(e){setErr((e as Error).message)}}return <Modal title="Nuevo registro" close={close}><form className="live-form" onSubmit={submit}>{type!=='clients'&&user.role!=='CLIENT'&&<label>Cliente<select required={type!=='payments'||!f.invoiceId} value={f.clientId||''} onChange={e=>S('clientId',e.target.value)}><option value="" disabled>Seleccionar…</option>{clients.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label>}{type==='clients'&&<><label>Nombre<input required onChange={e=>S('name',e.target.value)}/></label><label>Razón social<input onChange={e=>S('legalName',e.target.value)}/></label><label>RNC / Cédula<input onChange={e=>S('taxId',e.target.value)}/></label><label>Correo<input type="email" onChange={e=>S('email',e.target.value)}/></label><label>Teléfono<input onChange={e=>S('phone',e.target.value)}/></label><label>Condición de pago<input type="number" defaultValue="30" onChange={e=>S('paymentTermsDays',e.target.value)}/></label></>}{type==='sales'&&<><label>Oportunidad<input required onChange={e=>S('title',e.target.value)}/></label><label>Monto<input type="number" onChange={e=>S('amount',e.target.value)}/></label><label>Etapa<select onChange={e=>S('stage',e.target.value)}><option>QUALIFIED</option><option>PROPOSAL</option><option>NEGOTIATION</option><option>WON</option></select></label><label>Probabilidad<input type="number" defaultValue="25" onChange={e=>S('probability',e.target.value)}/></label><label>Próxima acción<input onChange={e=>S('nextAction',e.target.value)}/></label></>}{type==='projects'&&<><label>Proyecto<input required onChange={e=>S('name',e.target.value)}/></label><label>Presupuesto<input type="number" onChange={e=>S('budget',e.target.value)}/></label><label>Costo interno<input type="number" onChange={e=>S('internalCost',e.target.value)}/></label><label>MRR<input type="number" onChange={e=>S('recurringRevenue',e.target.value)}/></label><label>Entrega<input type="date" onChange={e=>S('dueDate',e.target.value)}/></label></>}{type==='proposals'&&<><label className="full">Título de la propuesta<input required onChange={e=>S('title',e.target.value)}/></label><label className="full">Resumen<textarea onChange={e=>S('summary',e.target.value)}/></label><label>Válida hasta<input type="date" onChange={e=>S('validUntil',e.target.value)}/></label><label>Forma de pago<input placeholder="50% inicio / 50% entrega" onChange={e=>S('paymentTerms',e.target.value)}/></label><div className="invoice-lines">{items.map((it,i)=><div key={i}><input value={it.description} onChange={e=>setItems(v=>v.map((x,j)=>j===i?{...x,description:e.target.value}:x))}/><input type="number" value={it.quantity} onChange={e=>setItems(v=>v.map((x,j)=>j===i?{...x,quantity:Number(e.target.value)}:x))}/><input type="number" value={it.unitPrice} onChange={e=>setItems(v=>v.map((x,j)=>j===i?{...x,unitPrice:Number(e.target.value)}:x))}/><input type="number" value={it.taxRate} onChange={e=>setItems(v=>v.map((x,j)=>j===i?{...x,taxRate:Number(e.target.value)}:x))}/></div>)}<button type="button" onClick={()=>setItems(v=>[...v,{description:'',quantity:1,unitPrice:0,taxRate:18}])}>＋ Añadir línea</button></div><div className="full milestones"><span className="mini-label">Hitos de pago (opcional)</span>{[0,1,2].map(i=><div key={i}><input placeholder={`Hito ${i+1} (ej. Al inicio)`} onChange={e=>S('milestones',Object.assign([...(f.milestones||[])],{[i]:{...(f.milestones?.[i]||{}),label:e.target.value}}))}/><input type="number" placeholder="%" onChange={e=>S('milestones',Object.assign([...(f.milestones||[])],{[i]:{...(f.milestones?.[i]||{}),percentage:Number(e.target.value)||undefined}}))}/></div>)}</div></>}{type==='billing'&&<><label>Tipo fiscal<select onChange={e=>S('fiscalType',e.target.value)}><option value="E31">E31 Crédito Fiscal</option><option value="E32">E32 Consumo</option><option value="B01">B01 Crédito Fiscal</option><option value="B02">B02 Consumo</option></select></label><label>Emitir<select onChange={e=>S('issue',e.target.value==='true')}><option value="true">Sí</option><option value="false">Borrador</option></select></label><div className="invoice-lines">{items.map((it,i)=><div key={i}><input value={it.description} onChange={e=>setItems(v=>v.map((x,j)=>j===i?{...x,description:e.target.value}:x))}/><input type="number" value={it.quantity} onChange={e=>setItems(v=>v.map((x,j)=>j===i?{...x,quantity:Number(e.target.value)}:x))}/><input type="number" value={it.unitPrice} onChange={e=>setItems(v=>v.map((x,j)=>j===i?{...x,unitPrice:Number(e.target.value)}:x))}/><input type="number" value={it.taxRate} onChange={e=>setItems(v=>v.map((x,j)=>j===i?{...x,taxRate:Number(e.target.value)}:x))}/></div>)}<button type="button" onClick={()=>setItems(v=>[...v,{description:'',quantity:1,unitPrice:0,taxRate:18}])}>＋ Añadir línea</button></div></>}{type==='payments'&&<><label>Factura<select defaultValue="" onChange={e=>{const i=invoices.find(x=>x.id===e.target.value);if(i){S('invoiceId',i.id);S('clientId',i.client_id);S('amount',Number(i.total)-Number(i.paid_amount))}}}><option value="">Sin factura</option>{invoices.filter(x=>!['PAID','VOID'].includes(x.status)).map(i=><option key={i.id} value={i.id}>{i.number} · {i.client_name}</option>)}</select></label><label>Monto<input required type="number" value={f.amount||''} onChange={e=>S('amount',e.target.value)}/></label><label>Método<select onChange={e=>S('method',e.target.value)}><option>TRANSFER</option><option>CARD</option><option>CASH</option></select></label><label>Referencia<input onChange={e=>S('reference',e.target.value)}/></label></>}{type==='support'&&<><label>Asunto<input required onChange={e=>S('subject',e.target.value)}/></label><label>Prioridad<select onChange={e=>S('priority',e.target.value)}><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>URGENT</option></select></label><label className="full">Descripción<textarea required onChange={e=>S('description',e.target.value)}/></label></>}{type==='assets'&&<><label>Activo / servicio<input required onChange={e=>S('name',e.target.value)}/></label><label>Tipo<select onChange={e=>S('type',e.target.value)}><option>DOMAIN</option><option>SSL</option><option>CLOUD</option><option>SERVER</option><option>LICENSE</option><option>SAAS</option><option>OTHER</option></select></label><label>Proveedor<input onChange={e=>S('provider',e.target.value)}/></label><label>Renovación<input type="date" onChange={e=>S('renewalDate',e.target.value)}/></label><label>Ciclo<select onChange={e=>S('billingCycle',e.target.value)}><option>MONTHLY</option><option>QUARTERLY</option><option>SEMIANNUAL</option><option>ANNUAL</option></select></label><label>Costo interno<input type="number" onChange={e=>S('recurringCost',e.target.value)}/></label><label>Precio cliente<input type="number" onChange={e=>S('recurringPrice',e.target.value)}/></label><label className="full recur-toggle"><input type="checkbox" onChange={e=>S('autoInvoice',e.target.checked)}/> Facturar automáticamente cada ciclo</label>{f.autoInvoice&&<><label>Próxima factura<input type="date" onChange={e=>S('nextInvoiceDate',e.target.value)}/></label><label>Tipo fiscal<select onChange={e=>S('fiscalType',e.target.value)}><option value="E31">E31</option><option value="E32">E32</option><option value="B01">B01</option><option value="B02">B02</option></select></label><label className="full">Descripción en factura<input placeholder="Hosting mensual · plan Business" onChange={e=>S('serviceDescription',e.target.value)}/></label></>}</>}{err&&<div className="live-error full">{err}</div>}<div className="live-actions"><button type="button" className="secondary-btn" onClick={close}>Cancelar</button><button className="primary-btn">Guardar</button></div></form></Modal>}
